// Tremor Accordion [v0.0.1]

import React from 'react';
import * as AccordionPrimitives from '@radix-ui/react-accordion';
import { RiAddLine } from '@remixicon/react';

import { cx } from '@/lib/utils';

const Accordion = AccordionPrimitives.Root;

Accordion.displayName = 'AccordionItem';

const AccordionTrigger = React.forwardRef<
  React.ElementRef<typeof AccordionPrimitives.Trigger>,
  React.ComponentPropsWithoutRef<typeof AccordionPrimitives.Trigger>
>(({ className, children, ...props }, forwardedRef) => (
  <AccordionPrimitives.Header className="flex">
    <AccordionPrimitives.Trigger
      className={cx(
        // base
        'group flex flex-1 cursor-pointer items-center justify-between py-3 text-left text-sm font-medium leading-none',
        // text color
        'text-gray-900 dark:text-gray-50',
        // disabled
        'data-[disabled]:cursor-default data-[disabled]:text-gray-400 dark:data-[disabled]:text-gray-600',
        //focus
        'focus-visible:z-10 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-inset focus-visible:ring-blue-500',
        className,
      )}
      {...props}
      ref={forwardedRef}
    >
      {children}
      <RiAddLine
        className={cx(
          // base
          'size-5 shrink-0 transition-transform duration-150 ease-[cubic-bezier(0.87,_0,_0.13,_1)] group-data-[state=open]:-rotate-45',
          // text color
          'text-gray-400 dark:text-gray-600',
          // disabled
          'group-data-[disabled]:text-gray-300 group-data-[disabled]:dark:text-gray-700',
        )}
        aria-hidden="true"
        focusable="false"
      />
    </AccordionPrimitives.Trigger>
  </AccordionPrimitives.Header>
));

AccordionTrigger.displayName = 'AccordionTrigger';

const AccordionContent = React.forwardRef<
  React.ElementRef<typeof AccordionPrimitives.Content>,
  React.ComponentPropsWithoutRef<typeof AccordionPrimitives.Content>
>(({ className, children, ...props }, forwardedRef) => (
  <AccordionPrimitives.Content
    ref={forwardedRef}
    className={cx(
      'transform-gpu data-[state=closed]:animate-accordionClose data-[state=open]:animate-accordionOpen',
    )}
    {...props}
  >
    <div
      className={cx(
        // base
        'overflow-hidden pb-4 text-sm',
        // text color
        'text-gray-700 dark:text-gray-200',
        className,
      )}
    >
      {children}
    </div>
  </AccordionPrimitives.Content>
));

AccordionContent.displayName = 'AccordionContent';

const AccordionItem = React.forwardRef<
  React.ElementRef<typeof AccordionPrimitives.Item>,
  React.ComponentPropsWithoutRef<typeof AccordionPrimitives.Item>
>(({ className, ...props }, forwardedRef) => (
  <AccordionPrimitives.Item
    ref={forwardedRef}
    className={cx(
      // base
      'overflow-hidden border-b first:mt-0',
      // border color
      'border-gray-200 dark:border-gray-800',
      className,
    )}
    tremor-id="tremor-raw"
    {...props}
  />
));

AccordionItem.displayName = 'AccordionItem';

export { Accordion, AccordionContent, AccordionItem, AccordionTrigger };

'use client';

import {
  RiCheckboxCircleFill,
  RiErrorWarningFill,
  RiLink,
} from '@remixicon/react';

import {
  Accordion,
  AccordionContent,
  AccordionItem,
  AccordionTrigger,
} from '@/components/Accordion';

interface Progress {
  current: number;
  total: number;
}

interface AuditDate {
  date: string;
  auditor: string;
}

interface Document {
  name: string;
  status: 'OK' | 'Needs update' | 'In audit';
}

interface Section {
  id: string;
  title: string;
  certified: string;
  progress: Progress;
  status: 'complete' | 'warning';
  auditDates: AuditDate[];
  documents: Document[];
}

export const sections: Section[] = [
  {
    id: 'item-1',
    title: 'CompTIA Security+',
    certified: 'ISO',
    progress: { current: 46, total: 46 },
    status: 'complete',
    auditDates: [
      { date: 'Dec 10, 2023', auditor: 'Max Duster' },
      { date: 'Dec 12, 2023', auditor: 'Emma Stone' },
    ],
    documents: [
      { name: 'policy_overview.xlsx', status: 'OK' },
      { name: 'employee_guidelines.xlsx', status: 'Needs update' },
      { name: 'compliance_checklist.xlsx', status: 'In audit' },
    ],
  },
  {
    id: 'item-2',
    title: 'SAFe Certifications',
    certified: 'IEC 2701',
    progress: { current: 32, total: 41 },
    status: 'warning',
    auditDates: [
      { date: 'Jan 15, 2024', auditor: 'Sarah Johnson' },
      { date: 'Jan 20, 2024', auditor: 'Mike Peters' },
    ],
    documents: [
      { name: 'certification_records.xlsx', status: 'OK' },
      { name: 'training_logs.xlsx', status: 'In audit' },
      { name: 'assessment_results.xlsx', status: 'Needs update' },
    ],
  },
  {
    id: 'item-3',
    title: 'PMP Certifications',
    certified: 'ISO',
    progress: { current: 21, total: 21 },
    status: 'complete',
    auditDates: [
      { date: 'Feb 5, 2024', auditor: 'Lisa Chen' },
      { date: 'Feb 8, 2024', auditor: 'Tom Wilson' },
    ],
    documents: [
      { name: 'project_documents.xlsx', status: 'OK' },
      { name: 'methodology_guide.xlsx', status: 'OK' },
      { name: 'best_practices.xlsx', status: 'In audit' },
    ],
  },
  {
    id: 'item-4',
    title: 'Cloud Certifications',
    certified: 'SOC 2',
    progress: { current: 21, total: 21 },
    status: 'complete',
    auditDates: [
      { date: 'Mar 1, 2024', auditor: 'Alex Kumar' },
      { date: 'Mar 5, 2024', auditor: 'Rachel Green' },
    ],
    documents: [
      { name: 'aws_certifications.xlsx', status: 'OK' },
      { name: 'azure_competencies.xlsx', status: 'OK' },
      { name: 'gcp_credentials.xlsx', status: 'In audit' },
      { name: 'cloud_security.xlsx', status: 'OK' },
    ],
  },
];

const getStatusIcon = (status: string) => {
  if (status === 'complete') {
    return (
      <RiCheckboxCircleFill className="size-[18px] shrink-0 text-emerald-600 dark:text-emerald-400" />
    );
  }
  return (
    <RiErrorWarningFill className="size-[18px] shrink-0 text-red-600 dark:text-red-400" />
  );
};

export default function Audits() {
  return (
    <div className="obfuscate">
      <Accordion type="multiple" className="mt-3">
        {sections.map((section) => (
          <AccordionItem key={section.id} value={section.id}>
            <AccordionTrigger className="py-5">
              <p className="flex w-full items-center justify-between pr-4">
                <span className="flex items-center gap-2.5">
                  <span>{section.title}</span>
                  <span className="inline-flex items-center rounded-full bg-gray-100 px-2 py-1 text-xs font-medium text-gray-700 dark:bg-gray-400/10 dark:text-gray-300">
                    {section.certified}
                  </span>
                </span>
                <span className="flex items-center gap-x-2 tabular-nums">
                  {getStatusIcon(section.status)}
                  {section.progress.current}/{section.progress.total}
                </span>
              </p>
            </AccordionTrigger>
            <AccordionContent>
              <div className="mt-2 grid grid-cols-1 gap-8 md:grid-cols-2">
                <div>
                  <p className="flex items-center justify-between text-sm font-medium text-gray-900 dark:text-gray-50">
                    <span>Audit round</span>
                    <span>Auditor</span>
                  </p>
                  <ul className="mt-1 divide-y divide-gray-200 text-sm text-gray-600 dark:divide-gray-800 dark:text-gray-400">
                    {section.auditDates.map((audit, index) => (
                      <li
                        key={index}
                        className="flex items-center justify-between py-2.5"
                      >
                        <span>{audit.date}</span>
                        <span>{audit.auditor}</span>
                      </li>
                    ))}
                  </ul>
                </div>
                <div>
                  <p className="flex items-center justify-between text-sm font-medium text-gray-900 dark:text-gray-50">
                    <span>Related documents</span>
                    <span>Status</span>
                  </p>
                  <ul className="mt-1 divide-y divide-gray-200 text-gray-600 dark:divide-gray-800 dark:text-gray-400">
                    {section.documents.map((doc, index) => (
                      <li
                        key={index}
                        className="flex items-center justify-between py-2.5 text-sm"
                      >
                        <a
                          href="#"
                          className="flex items-center gap-2 text-blue-500 hover:underline hover:underline-offset-4 dark:text-blue-500"
                        >
                          <RiLink
                            className="size-4 shrink-0"
                            aria-hidden="true"
                          />
                          {doc.name}
                        </a>
                        <div className="flex items-center gap-2">
                          <button
                            type="button"
                            className="hover:text-gray-900 hover:underline hover:underline-offset-4 hover:dark:text-gray-50"
                          >
                            Edit
                          </button>
                          <span
                            className="h-4 w-px bg-gray-300 dark:bg-gray-700"
                            aria-hidden="true"
                          />
                          <button
                            type="button"
                            className="hover:text-gray-900 hover:underline hover:underline-offset-4 hover:dark:text-gray-50"
                          >
                            Re-Upload
                          </button>
                        </div>
                      </li>
                    ))}
                  </ul>
                </div>
              </div>
            </AccordionContent>
          </AccordionItem>
        ))}
      </Accordion>
    </div>
  );
}

@tailwind base;
@tailwind components;
@tailwind utilities;

:root {
  font-variant-ligatures: none;
}

@font-face {
  font-family: 'JetBrainsMono';
  font-weight: 100 900;
  font-display: block;
  font-style: normal;
  font-named-instance: 'Regular';
  src: url('/fonts/JetBrainsMono[wght].woff2') format('woff2');
}

/* Remove Safari input shadow on mobile */
input[type='text'],
input[type='email'] {
  -webkit-appearance: none;
  -moz-appearance: none;
  appearance: none;
}

@layer utilities {
  .mask {
    mask-image: radial-gradient(rgba(0, 0, 0, 1) 0%, transparent 80%);
  }

  .shadow-tremor {
    @apply shadow-xl shadow-black/5;
  }
}

@keyframes draw {
  to {
    stroke-dashoffset: 0;
  }
}

@keyframes slideUpFade {
  from {
    opacity: 0;
    transform: translateY(20px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

